PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS metadata(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS episodes(id TEXT PRIMARY KEY,policy TEXT NOT NULL,execution_mode TEXT NOT NULL,benchmark TEXT NOT NULL,config_json TEXT NOT NULL,config_hash TEXT NOT NULL,bootstrap_id TEXT,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agents(episode_id TEXT NOT NULL REFERENCES episodes(id),agent_id TEXT NOT NULL,state_json TEXT NOT NULL,PRIMARY KEY(episode_id,agent_id));
CREATE TABLE IF NOT EXISTS rounds(episode_id TEXT NOT NULL REFERENCES episodes(id),round_index INTEGER NOT NULL,status TEXT NOT NULL,snapshot_json TEXT NOT NULL,snapshot_hash TEXT NOT NULL,PRIMARY KEY(episode_id,round_index));
CREATE TABLE IF NOT EXISTS plan_versions(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL,parent_hash TEXT NOT NULL,payload TEXT NOT NULL,content_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS round_submissions(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,agent_id TEXT NOT NULL,plan_version_id TEXT NOT NULL REFERENCES plan_versions(id),payload TEXT NOT NULL,PRIMARY KEY(episode_id,round_index,agent_id),FOREIGN KEY(episode_id,round_index) REFERENCES rounds(episode_id,round_index));
CREATE TABLE IF NOT EXISTS priority_orders(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(episode_id,round_index));
CREATE TABLE IF NOT EXISTS invitations(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,agent_id TEXT NOT NULL,status TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(episode_id,round_index,agent_id));
CREATE TABLE IF NOT EXISTS holds(id TEXT PRIMARY KEY,episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,agent_id TEXT NOT NULL,amount TEXT NOT NULL,status TEXT NOT NULL,UNIQUE(episode_id,round_index,agent_id));
CREATE TABLE IF NOT EXISTS candidates(hash TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS prechecks(id TEXT PRIMARY KEY,episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,agent_id TEXT NOT NULL,candidate_hash TEXT NOT NULL,passed INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS final_allocations(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,agent_id TEXT NOT NULL,ticket_id TEXT UNIQUE,x INTEGER NOT NULL CHECK(x IN(0,1)),payment TEXT NOT NULL,status TEXT NOT NULL,PRIMARY KEY(episode_id,round_index,agent_id));
CREATE TABLE IF NOT EXISTS eval_tickets(id TEXT PRIMARY KEY,job_id TEXT NOT NULL UNIQUE,episode_id TEXT NOT NULL REFERENCES episodes(id),round_index INTEGER NOT NULL,agent_id TEXT NOT NULL,candidate_hash TEXT NOT NULL,contract_hash TEXT NOT NULL,panel_hash TEXT NOT NULL,phase_epoch INTEGER NOT NULL,status TEXT NOT NULL,fence INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL,UNIQUE(episode_id,round_index,agent_id));
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,ticket_id TEXT NOT NULL UNIQUE REFERENCES eval_tickets(id),status TEXT NOT NULL,fence INTEGER NOT NULL,receipt TEXT);
CREATE TABLE IF NOT EXISTS verified_results(job_id TEXT PRIMARY KEY REFERENCES jobs(id),candidate_hash TEXT NOT NULL,payload TEXT NOT NULL,payload_hash TEXT NOT NULL,fence INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS instance_results(job_id TEXT NOT NULL REFERENCES jobs(id),instance_index INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(job_id,instance_index));
CREATE TABLE IF NOT EXISTS settlements(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,agent_id TEXT NOT NULL,payment TEXT NOT NULL,reward TEXT NOT NULL,wealth_before TEXT NOT NULL,wealth_after TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(episode_id,round_index,agent_id));
CREATE TABLE IF NOT EXISTS wallet_entries(operation_key TEXT PRIMARY KEY,episode_id TEXT NOT NULL,agent_id TEXT NOT NULL,kind TEXT NOT NULL,amount TEXT NOT NULL,round_index INTEGER);
CREATE TABLE IF NOT EXISTS checkpoints(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,content_hash TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(episode_id,round_index));
CREATE TABLE IF NOT EXISTS warm_checkpoints(id TEXT PRIMARY KEY,payload TEXT NOT NULL,content_hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS arm_clones(episode_id TEXT PRIMARY KEY REFERENCES episodes(id),warm_id TEXT NOT NULL REFERENCES warm_checkpoints(id),manifest TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS public_board_versions(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(episode_id,round_index));
CREATE TABLE IF NOT EXISTS artifact_refs(hash TEXT PRIMARY KEY,kind TEXT NOT NULL,size_bytes INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS resource_usage(id INTEGER PRIMARY KEY AUTOINCREMENT,episode_id TEXT NOT NULL,round_index INTEGER,agent_id TEXT,phase TEXT NOT NULL,cpu_seconds REAL NOT NULL,wall_seconds REAL NOT NULL,llm_calls INTEGER NOT NULL,tokens INTEGER NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY AUTOINCREMENT,episode_id TEXT,round_index INTEGER,kind TEXT NOT NULL,payload TEXT NOT NULL,previous_hash TEXT NOT NULL,hash TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS dispatch_outbox(job_id TEXT PRIMARY KEY REFERENCES jobs(id),status TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS publication_outbox(episode_id TEXT NOT NULL,round_index INTEGER NOT NULL,status TEXT NOT NULL,PRIMARY KEY(episode_id,round_index));
CREATE TABLE IF NOT EXISTS phase_transitions(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS edit_grants(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_links(plan_version_id TEXT NOT NULL,evidence_id TEXT NOT NULL,PRIMARY KEY(plan_version_id,evidence_id));
CREATE TABLE IF NOT EXISTS context_manifests(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS lessons(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS policy_statistics(episode_id TEXT NOT NULL,agent_id TEXT NOT NULL,payload TEXT NOT NULL,PRIMARY KEY(episode_id,agent_id));
CREATE TABLE IF NOT EXISTS contracts(hash TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS seed_manifests(hash TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS report_manifests(id TEXT PRIMARY KEY,payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS events_episode ON events(episode_id,round_index);
CREATE INDEX IF NOT EXISTS tickets_round ON eval_tickets(episode_id,round_index,status);
